head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > getKeyInfo]<br/>Key 의 ID 또는 인덱스값을 사용하여 특정 Key 의 정보를 객체로 반환합니다.",
    "validation" : [
        "keyInfo(필수) 파라미터로 세부 정보를 조회하려는 Key 의 ID 값을 설정합니다.",        
        "반환값으로 파라미터에 해당하는 Key 의 세부 정보를 객체로 반환합니다.",
        "반환된 객체는 Key 에 설정된 모든 속성들이 '속성명:속성값' 형태의 Key-Value 쌍으로 구성됩니다.",
        "파라미터에 해당하는 Key 가 없는 경우 undefined 를 반환합니다.",
        "Key 에 설정되지 않은 속성은 Key-Value 쌍으로 생성되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };    

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);      

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strInput = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataMap ' + strNameSpace + ' id="target1" baseNode="map">';        
    strTarget += '<w2:keyInfo>';
    strTarget += '<w2:key dataType="text" id="key1" name="name1"></w2:key>';
    strTarget += '<w2:key dataType="number" id="key2" name="name2"></w2:key>';
    strTarget += '<w2:key dataType="bigDecimal" id="key3" name="name3"></w2:key>';
    strTarget += '<w2:key dataType="date" id="key4" name="name4"></w2:key>';
    strTarget += '<w2:key dataType="time" id="key5" name="name5"></w2:key>';
    strTarget += '<w2:key dataType="json" id="key6" name="name6"></w2:key>';
    strTarget += '</w2:keyInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<key1><![CDATA[dm_data1]]></key1>';
    strTarget += '<key2><![CDATA[123]]></key2>';
    strTarget += '<key3><![CDATA[123.456]]></key3>';
    strTarget += '<key4><![CDATA[20260204]]></key4>';
    strTarget += '<key5><![CDATA[112430]]></key5>';
    strTarget += '<key6><![CDATA[{prop:"1"}]]></key6>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataMap>';      

    $p.data.create(strTarget);

	// input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');
}   



scwin.btn_getKeyInfo_onclick = function (e) {
    let keyId = par_keyInfo.getText();
    let rtn = target1.getKeyInfo(keyId);    
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("result : " + jsonString); 
};
